import type { User } from '../../domain/entities/User';
import type { Email } from '../../domain/value-objects/Email';

export const USER_REPOSITORY = 'USER_REPOSITORY';

export interface IUserRepository {
  /**
   * Insert or update — the id is generated by the domain, never by the repository.
   *
   * MUST reject with EmailAlreadyUsedError (application/errors/AuthErrors.ts) when the email is
   * already taken, and with UsernameAlreadyUsedError when the username is (compared on
   * User.usernameKey, so "Pokemon" and "pokemon" collide), including when two requests race.
   * The findByEmail()/findByUsername() checks made by the use cases are a UX shortcut (fail fast,
   * clear error) — they do NOT prevent two concurrent requests from both passing them. Only a
   * unique constraint in the store (email, and the username key), with this method translating its
   * violation into the matching error, actually guarantees no duplicate.
   */
  save(user: User): Promise<User>;
  findById(id: string): Promise<User | null>;
  findByEmail(email: Email): Promise<User | null>;
  /** Looks up on User.usernameKey(username): case and spacing variants find the same user. */
  findByUsername(username: string): Promise<User | null>;
}
